 function agreement(agree){const suggestion=selected?C.suggestion(input,hash,selected,workingAgent):null;if(agree&&suggestion)choose(suggestion.action,true);else{draft.agree=false;editing=true;action=null;projection=null;renderActions();}}
 async function switchDataset(dataset){if(dataset===ws.dataset_id)return;cacheDraft();const copy=ownedCopies.filter(s=>s.dataset_id===dataset&&!s.complete).sort((a,b)=>String(b.updated_at).localeCompare(String(a.updated_at)))[0];if(copy)return attempt(()=>openWorkspace(copy.workspace_id));$('#data-source').value=ws.dataset_id;await openData();if(local()||(remote()&&PrivateData.connected)){$('#inline-dataset-choice').value=dataset;await loadServer();}else message(remote()?'Connect to load '+dataset+'.':'Load the private package for '+dataset+' to curate it.');}
 async function openData(show=true){await database();origin=active()?null:{...currentCase(),target_id:comparisonTarget(currentCase())?Number(comparisonTarget(currentCase()).slice(2)):null};if(show!==false)$('#inline-working-dialog').showModal();message('');renderConnection();const copies=(await all('workspaces')).filter(s=>s.reviewer===reviewerId).sort((a,b)=>String(b.updated_at).localeCompare(String(a.updated_at)));const dataKey=active()?input.data.source_sha256:origin?.mat_sha256;$('#inline-use-loaded').hidden=!dataKey;$('#inline-use-loaded').disabled=true;if(dataKey){const tx=db.transaction('datasets'),check=tx.objectStore('datasets').getKey(dataKey);check.onsuccess=()=>{$('#inline-use-loaded').hidden=!check.result;$('#inline-use-loaded').disabled=false;$('#inline-use-loaded').onclick=()=>attempt(async()=>{const data=await read('datasets',dataKey);if(!data)throw Error('Private data is no longer available');await start(data,origin);});};}$('#inline-workspace-choice').innerHTML='<option value="">Choose a saved session…</option>'+copies.map(s=>'<option value="'+s.workspace_id+'">'+escapeHtml(s.dataset_id)+' · v'+s.version+'</option>').join('');if(local())await populateServerChoices();else if(remote()&&PrivateData.connected){try{await populateServerChoices();}catch(e){message(e.message);renderConnection();}}}
