 async function mount(){datasetHandler=$('#data-source').onchange;agentHandler=$('#agent-choice').onchange;const host=document.createElement('div');host.innerHTML=`<dialog id="inline-working-dialog"><div class="modal-heading"><h2>Load data</h2><button class="icon-button" id="inline-working-close" aria-label="Close private data">×</button></div><p>Load spike data once. Actions are saved after confirmation.</p><section id="inline-private-connection" hidden><h3>Private Runpod data</h3><div id="inline-private-login"><label>Access key<input id="inline-private-key" type="password" autocomplete="off" spellcheck="false"></label><button class="button primary" id="inline-private-connect">Connect &amp; load this channel</button><p class="input-help">Use the private key saved on your Runpod. No manual data transfer is needed.</p></div><div id="inline-private-connected" hidden><span id="inline-private-name"></span> · Connected <button class="button small" id="inline-private-disconnect">Disconnect</button></div></section><section id="inline-local-inputs"><label>Dataset<select id="inline-dataset-choice"></select></label><button class="button primary" id="inline-start-server">Start / resume selected data</button><button class="button" id="inline-download-package">Download private package</button><details id="inline-add-mat"><summary>Add a new MAT dataset</summary><label>Recording / session ID<input id="inline-recording-id" maxlength="120"></label><label>MAT file<input id="inline-new-mat" type="file" accept=".mat"></label><button class="button" id="inline-upload-mat">Upload MAT &amp; validate</button><label>Or a MAT path on Runpod<input id="inline-server-mat" placeholder="/workspace/spike-sorting-agent/…/spikes.mat"></label><button class="button" id="inline-import-server-mat">Import server MAT &amp; validate</button></details></section><details id="inline-other-data"><summary>Import other data or restore a session</summary><section><h3>Add sorted data</h3><label>Recording / session ID<input id="inline-generic-recording" maxlength="100"></label><label>Sorted-spike JSON, or Phy/Kilosort files<input id="inline-generic-files" type="file" multiple accept=".json,.npy,.dat,.bin,.tsv"></label><div class="input-actions"><button class="button primary" id="inline-import-generic">Validate &amp; open</button><button class="button" id="inline-import-template">JSON template</button><button class="button" id="inline-phy-template">Phy metadata template</button></div><details class="evidence-details"><summary>Required files</summary><p>JSON: sampling_rate_hz, times_seconds, spike_clusters, waveforms (one real row per spike). Phy/Kilosort: metadata.json, spike_times.npy, spike_clusters.npy and waveforms.npy; alternatively include the raw recording and extraction metadata. A template mean cannot replace member waveforms. Browser limit: 256 MiB total.</p></details></section><section><button class="button primary" id="inline-use-loaded" hidden>Start / resume locally loaded data</button><label>Dataset or saved session file<input type="file" id="inline-private-file" accept=".json,.gz"></label><button class="button" id="inline-import-private">Import into this browser</button><p id="inline-private-file-help">Free site: import a private package exported from Runpod. Data stays in this browser.</p></section></details><section><label>Saved sessions<select id="inline-workspace-choice"></select></label><button class="button" id="inline-open-workspace">Open session</button><button class="button" id="inline-export-workspace">Export session</button><button class="button" id="inline-export-result">Export sorting result</button></section><p id="inline-working-message" role="status"></p></dialog>`;document.body.append(host.firstElementChild);window.addEventListener('private-data-connection',renderConnection);$('#inline-private-connect').onclick=()=>attempt(async()=>{const field=$('#inline-private-key'),key=field.value.trim();field.value='';message('Connecting to private Runpod data…');await PrivateData.connect(key);await populateServerChoices();await loadSelectedServer();});$('#inline-private-key').onkeydown=e=>{if(e.key==='Enter'){e.preventDefault();$('#inline-private-connect').click();}};$('#inline-private-disconnect').onclick=()=>attempt(async()=>{await PrivateData.disconnect();message('Disconnected. Your saved browser session is retained.');});$('#inline-start-working').onclick=openData;$('#inline-data-link').onclick=()=>{$('#data-modal').close();openData();};$('#inline-return-snapshots').onclick=exit;$('#inline-working-undo').onclick=undo;$('#inline-cancel-preview').onclick=cancelChoice;$('#inline-working-close').onclick=()=>$('#inline-working-dialog').close();$('#inline-import-template').onclick=()=>download(WorkingImport.template(),'sorted-spike-input.json',false);$('#inline-phy-template').onclick=()=>download({sampling_rate_hz:null,spike_time_units:'samples',quality_metric:null,quality_direction:'higher',quality_provenance:'',waveform_channel_index:0,recording_file:'recording.dat',dtype:'int16',n_channels:null,channel_index:null,pre_samples:15,post_samples:30},'metadata.json',false);$('#inline-import-generic').onclick=()=>attempt(async()=>{message('Validating real input rows locally…');const data=await WorkingImport.parse([...$('#inline-generic-files').files],$('#inline-generic-recording').value.trim());if(data.schema!==C.SCHEMA)throw Error('Use the private-package input below for a saved workspace');origin=null;await start(data);});$('#inline-start-server').onclick=loadServer;$('#inline-upload-mat').onclick=()=>importMAT(false);$('#inline-import-server-mat').onclick=()=>importMAT(true);$('#inline-download-package').onclick=()=>attempt(async()=>{const r=await fetch('/api/curation/package?dataset_id='+encodeURIComponent($('#inline-dataset-choice').value));if(!r.ok)throw Error('Private package unavailable');const data=await unpack(await r.blob());await download(data,data.dataset_id+'.working.json');message('Private package downloaded. It was not published.');});$('#inline-import-private').onclick=()=>attempt(async()=>{const file=$('#inline-private-file').files[0];if(!file)throw Error('Choose a private package');message('Reading and validating the private file locally…');const value=await unpack(file);if(value.schema==='spikeagent-working-workspace-v1'){const p=await verify(value.dataset),s=C.clone(value.state);validateState(value.dataset,s,p);if(await C.stateHash(p,s)!==value.state_sha256)throw Error('Imported workspace hash mismatch');s.parent_workspace={workspace_id:s.workspace_id,version:s.version,previous_reviewer:s.reviewer};s.workspace_id=crypto.randomUUID();s.reviewer=reviewerId;s.version++;s.events.push({id:crypto.randomUUID(),type:'continued_imported_workspace',version:s.version,reviewer:reviewerId,timestamp:new Date().toISOString(),state_after:value.state_sha256});s.updated_at=new Date().toISOString();await write('datasets',value.dataset);await write('workspaces',s);await activate(value.dataset,s);}else await start(value,origin?.mat_sha256===value.source_sha256?origin:null);});$('#inline-open-workspace').onclick=()=>attempt(()=>openWorkspace($('#inline-workspace-choice').value));$('#inline-export-workspace').onclick=()=>attempt(()=>exportWorkspace());$('#inline-export-result').onclick=()=>attempt(()=>exportResult());try{await database();const id=localStorage.getItem('spikeagent-inline-working-active:'+reviewerId);if(id&&!new URLSearchParams(location.search).has('case')){const s=await read('workspaces',id);if(s?.reviewer===reviewerId)await openWorkspace(id);}}catch(e){toast(e.message);}}
 async function acceptLive(result){if(!active()||result.case_id!==virtual.id||result.state_sha256!==hash||!result.request_id||!result.decision||!['KEEP','SPLIT','MERGE','NOT_MERGE','DISCARD','DEFER'].includes(result.decision.action))throw Error('Live response belongs to another working state');const row={state_sha256:hash,phase:selected.phase,source:selected.source,target:selected.target,agent_id:'Agent_3',action:result.decision.action,rationale:result.decision.rationale,origin:'explicit-current-state-request',request_id:result.request_id,provider:result.provider,model:result.model,timestamp:result.timestamp};input.data.agent_suggestions=[...(input.data.agent_suggestions||[]),row];await write('datasets',input.data);workingAgent='Agent_3';render();}
